from bcc import BPF, SymbolCache, bcc_symbol
import ctypes as ct
import time
import sys
import os
import signal

# BPF program for counting strlen return values
bpf_count_code = """
BPF_HISTOGRAM(ret_hist);

int count_strlen_ret(struct pt_regs *ctx) {
    int ret = PT_REGS_RC(ctx);
    ret_hist.increment(bpf_log2l(ret));
    return 0;
}
"""

# BPF program for submitting resolver and implementation addresses
bpf_addr_code = """
BPF_HASH(addr_map, u64, u64);

int submit_strlen_addr(struct pt_regs *ctx) {
    u64 resolver_addr = 0;
    u64 impl_addr = 0;
    bpf_usdt_readarg(1, ctx, &resolver_addr);
    bpf_usdt_readarg(2, ctx, &impl_addr);
    addr_map.update(&resolver_addr, &impl_addr);
    return 0;
}
"""

def get_strlen_symbol(libc_path):
    # Find the symbol for strlen (may be indirect)
    sym = bcc_symbol()
    addr = sym.resolve_name(libc_path, "strlen")
    if addr is None:
        raise Exception("Could not find strlen symbol in %s" % libc_path)
    return addr

def set_resolver_and_impl_addr(libc_path):
    # Find resolver and implementation addresses for strlen
    sym = bcc_symbol()
    resolver_addr = sym.resolve_name(libc_path, "__strlen_sse2")
    if resolver_addr is None:
        resolver_addr = sym.resolve_name(libc_path, "__strlen_avx2")
    if resolver_addr is None:
        resolver_addr = sym.resolve_name(libc_path, "__strlen_generic")
    if resolver_addr is None:
        raise Exception("Could not find strlen implementation in %s" % libc_path)
    impl_addr = resolver_addr
    return resolver_addr, impl_addr

def find_impl_offset(libc_path, impl_addr):
    # Find offset of implementation function from base
    base = bcc_symbol().resolve_name(libc_path, None)
    if base is None:
        raise Exception("Could not find base address for %s" % libc_path)
    return impl_addr - base

def print_histogram(bpf):
    print("strlen() return value histogram:")
    bpf["ret_hist"].print_log2_hist("strlen return")

def clear_histogram(bpf):
    bpf["ret_hist"].clear()

def main():
    libc_path = BPF.find_library("c")
    if not libc_path:
        print("Could not find libc")
        sys.exit(1)

    strlen_addr = get_strlen_symbol(libc_path)
    resolver_addr, impl_addr = set_resolver_and_impl_addr(libc_path)
    impl_offset = find_impl_offset(libc_path, impl_addr)

    bpf = BPF(text=bpf_count_code)
    # Attach uretprobe to strlen implementation
    bpf.attach_uretprobe(name=libc_path, sym="strlen", fn_name="count_strlen_ret", offset=impl_offset)

    print("Tracing strlen() return values... Hit Ctrl-C to end.")

    try:
        while True:
            time.sleep(1)
            print_histogram(bpf)
            clear_histogram(bpf)
    except KeyboardInterrupt:
        pass

if __name__ == "__main__":
    main()
